insert into public.papers (id, project_id, owner, title, authors, journal, year, doi, section, topic, note, essential, position) values
('a79e028c-93ca-5c7e-b368-5307109faff9', '00000000-0000-4000-8000-000000000001', null, 'Why gold is the noblest of all the metals', 'Hammer & Nørskov', 'Nature', 1995, '10.1038/376238a0', 'core', 'Electronic structure: the d-band model', 'Two pages that introduce the idea that adsorption strength tracks the d-band position. Everything about descriptors starts here.', true, 0),
('9944b711-5fc5-5f07-bbe4-0da650437906', '00000000-0000-4000-8000-000000000001', null, 'CO chemisorption at metal surfaces and overlayers', 'Hammer, Morikawa & Nørskov', 'Phys. Rev. Lett.', 1996, '10.1103/PhysRevLett.76.2141', 'core', 'Electronic structure: the d-band model', 'The d-band centre applied to CO binding across metals and overlayers. Directly relevant to any argument about *CO coverage.', false, 1),
('51694400-ed64-5c84-9709-6fe26387618b', '00000000-0000-4000-8000-000000000001', null, 'Effect of strain on the reactivity of metal surfaces', 'Mavrikakis, Hammer & Nørskov', 'Phys. Rev. Lett.', 1998, '10.1103/PhysRevLett.81.2819', 'core', 'Electronic structure: the d-band model', 'Shows that lattice strain shifts the d-band and with it adsorption energies. This is the basis for later strain-engineered Pt alloys.', false, 2),
('3f8f474e-282f-52d9-b710-4c8519ba5b9c', '00000000-0000-4000-8000-000000000001', null, 'Theoretical surface science and catalysis: calculations and concepts', 'Hammer & Nørskov', 'Adv. Catal.', 2000, null, 'core', 'Electronic structure: the d-band model', 'The long-form treatment of the d-band model. Read it once carefully and refer back to it often.', true, 3),
('2dc127e9-26b7-5511-b017-52b38359ff41', '00000000-0000-4000-8000-000000000001', null, 'Role of strain and ligand effects in the modification of the electronic and chemical properties of bimetallic surfaces', 'Kitchin, Nørskov, Barteau & Chen', 'Phys. Rev. Lett.', 2004, '10.1103/PhysRevLett.93.156801', 'core', 'Electronic structure: the d-band model', 'Separates the strain and ligand contributions in bimetallics. You will need the distinction whenever someone says an alloy is “electronically modified”.', false, 4),
('58673b77-1f11-54b2-8fb2-4cb2df224fde', '00000000-0000-4000-8000-000000000001', null, 'Universality in heterogeneous catalysis', 'Nørskov et al.', 'J. Catal.', 2002, '10.1006/jcat.2002.3615', 'core', 'Scaling, volcanoes and the computational electrode', 'Brønsted–Evans–Polanyi relations across many metals, which give the volcano its shape.', false, 5),
('f1f26559-c6f5-5f0e-adbc-fa09ee0cedfa', '00000000-0000-4000-8000-000000000001', null, 'Origin of the overpotential for oxygen reduction at a fuel-cell cathode', 'Nørskov, Rossmeisl et al.', 'J. Phys. Chem. B', 2004, '10.1021/jp047349j', 'core', 'Scaling, volcanoes and the computational electrode', 'Introduces the computational hydrogen electrode, the method behind most free-energy diagrams in electrocatalysis.', true, 6),
('4445f989-a5fd-51e2-aa9b-d36aa8046b80', '00000000-0000-4000-8000-000000000001', null, 'Trends in the exchange current for hydrogen evolution', 'Nørskov, Bligaard et al.', 'J. Electrochem. Soc.', 2005, '10.1149/1.1856988', 'core', 'Scaling, volcanoes and the computational electrode', 'The HER volcano with ΔG_H as the descriptor. Also read Schmickler''s published comment on it to see the main criticism.', true, 7),
('27770e1d-ad95-5e8b-a4c7-f44c6e862d17', '00000000-0000-4000-8000-000000000001', null, 'Scaling properties of adsorption energies for hydrogen-containing molecules on transition-metal surfaces', 'Abild-Pedersen, Nørskov et al.', 'Phys. Rev. Lett.', 2007, '10.1103/PhysRevLett.99.016105', 'core', 'Scaling, volcanoes and the computational electrode', 'Shows that AHx binding scales with A binding. This is where the “scaling relations limit catalysis” argument comes from.', true, 8),
('ad443a17-5ac7-562e-9e0d-aca090945abf', '00000000-0000-4000-8000-000000000001', null, 'Universality in oxygen evolution electrocatalysis on oxide surfaces', 'Man, Rossmeisl et al.', 'ChemCatChem', 2011, '10.1002/cctc.201000397', 'core', 'Scaling, volcanoes and the computational electrode', 'The *OOH/*OH scaling relation, which sets a minimum theoretical OER overpotential of about 0.37 V on oxides.', true, 9),
('a5d328af-854a-5ff6-81b7-33b9bfbd88bf', '00000000-0000-4000-8000-000000000001', null, 'Towards the computational design of solid catalysts', 'Nørskov, Bligaard, Rossmeisl & Christensen', 'Nat. Chem.', 2009, '10.1038/nchem.121', 'core', 'Scaling, volcanoes and the computational electrode', 'A readable summary of the descriptor-based design approach as it stood in 2009.', false, 10),
('166e78e4-2d03-5901-a4a3-80de3fc567a4', '00000000-0000-4000-8000-000000000001', null, 'Density functional theory in surface chemistry and catalysis', 'Nørskov, Abild-Pedersen, Studt & Bligaard', 'PNAS', 2011, '10.1073/pnas.1006652108', 'core', 'Scaling, volcanoes and the computational electrode', 'A short perspective on what DFT can and cannot reliably tell you about catalysts.', false, 11),
('bd6e5ee4-461f-5831-af77-30408d813a8e', '00000000-0000-4000-8000-000000000001', null, 'From the Sabatier principle to a predictive theory of transition-metal heterogeneous catalysis', 'Medford, Nørskov et al.', 'J. Catal.', 2015, '10.1016/j.jcat.2014.12.033', 'core', 'Scaling, volcanoes and the computational electrode', 'Traces how the Sabatier principle became quantitative through descriptors and microkinetics.', false, 12),
('fa80d2af-c5d9-5eee-bb73-0157d9f0d42b', '00000000-0000-4000-8000-000000000001', null, 'Thermodynamic theory of multi-electron transfer reactions: implications for electrocatalysis', 'Koper', 'J. Electroanal. Chem.', 2011, '10.1016/j.jelechem.2010.10.004', 'core', 'Multi-electron thermodynamics', 'Explains why two-electron reactions can be near-reversible while four- and six-electron reactions cannot. Useful framing for a 6e⁻ product like methanol.', true, 13),
('dcf68675-51b7-58ac-8974-521cc5462e44', '00000000-0000-4000-8000-000000000001', null, 'Theory of multiple proton–electron transfer reactions and its implications for electrocatalysis', 'Koper', 'Chem. Sci.', 2013, '10.1039/c3sc50205h', 'core', 'Multi-electron thermodynamics', 'What happens when proton and electron transfer decouple: pH dependence on the RHE scale and an optimal pH. Read before any pH-dependence experiment.', true, 14),
('74fea64e-0595-5503-81d0-9aac5c462e44', '00000000-0000-4000-8000-000000000001', null, 'Structural and electronic effects in heterogeneous electrocatalysis: toward a rational design of electrocatalysts', 'Bandarenka & Koper', 'J. Catal.', 2013, '10.1016/j.jcat.2013.05.006', 'core', 'Multi-electron thermodynamics', 'Reviews how geometric and electronic effects each shift activity, with examples across reactions.', false, 15),
('4b1e6de8-bf88-52e9-9464-a2ed9a2eed16', '00000000-0000-4000-8000-000000000001', null, 'Combining theory and experiment in electrocatalysis: insights into materials design', 'Seh, Kibsgaard, Dickens, Chorkendorff, Nørskov & Jaramillo', 'Science', 2017, '10.1126/science.aad4998', 'core', 'Bridging theory and experiment', 'The best single map of the field. Read it first, then return to it after you finish each ring.', true, 16),
('b41ca489-3f09-5966-8ea7-37ee75cad085', '00000000-0000-4000-8000-000000000001', null, 'Enhancing the connection between computation and experiments in electrocatalysis', 'Resasco et al.', 'Nat. Catal.', 2022, null, 'core', 'Bridging theory and experiment', 'A perspective on measuring intrinsic kinetics, building realistic active-site models, and linking calculated energetics to measured rates.', true, 17),
('933967cb-5e0d-522d-ac91-09f186a5d07b', '00000000-0000-4000-8000-000000000001', null, 'Biomimetic hydrogen evolution: MoS2 nanoparticles as catalyst for hydrogen evolution', 'Hinnemann, Nørskov et al.', 'J. Am. Chem. Soc.', 2005, '10.1021/ja0504690', 'rxn', 'Hydrogen (HER/HOR)', 'Uses the ΔG_H descriptor to predict that MoS2 edges should be active. This is a clear example of theory leading experiment.', true, 18),
('654ebff8-a230-5427-b34c-4d74ea1a821a', '00000000-0000-4000-8000-000000000001', null, 'Computational high-throughput screening of electrocatalytic materials for hydrogen evolution', 'Greeley, Jaramillo, Bonde, Chorkendorff & Nørskov', 'Nat. Mater.', 2006, '10.1038/nmat1752', 'rxn', 'Hydrogen (HER/HOR)', 'Combines a descriptor with a stability criterion to screen alloys, and then tests the top prediction (BiPt) experimentally.', true, 19),
('32b8b853-be6c-5fcd-be3f-88421466b1e6', '00000000-0000-4000-8000-000000000001', null, 'Identification of active edge sites for electrochemical H2 evolution from MoS2 nanocatalysts', 'Jaramillo, Chorkendorff et al.', 'Science', 2007, '10.1126/science.1141483', 'rxn', 'Hydrogen (HER/HOR)', 'Uses STM to count edge sites and shows that activity scales with edge length, not area. This is the standard example of active-site counting.', true, 20),
('f0a20fe6-a1b1-5c20-9015-62cde852ba83', '00000000-0000-4000-8000-000000000001', null, 'Hydrogen evolution on supported incomplete cubane-type [Mo3S4]4+ electrocatalysts', 'Jaramillo, Chorkendorff et al.', 'J. Phys. Chem. C', 2008, '10.1021/jp802695e', 'rxn', 'Hydrogen (HER/HOR)', 'A molecular cluster that mimics the MoS2 edge. It sits between molecular and surface catalysis, much as CoPc does.', false, 21),
('677333ab-088b-56cd-9b0d-326c22d0f76d', '00000000-0000-4000-8000-000000000001', null, 'Hydrogen oxidation and evolution reaction kinetics on platinum: acid vs alkaline electrolytes', 'Sheng, Gasteiger & Shao-Horn', 'J. Electrochem. Soc.', 2010, '10.1149/1.3483106', 'rxn', 'Hydrogen (HER/HOR)', 'Shows that HER/HOR on Pt is about two orders of magnitude slower in base. This started a decade of debate over the cause.', true, 22),
('c1330981-feeb-5787-900a-e41dcafc7f3d', '00000000-0000-4000-8000-000000000001', null, 'Enhancing hydrogen evolution activity in water splitting by tailoring Li⁺-Ni(OH)2-Pt interfaces', 'Subbaraman, Markovic et al.', 'Science', 2011, '10.1126/science.1211934', 'rxn', 'Hydrogen (HER/HOR)', 'The bifunctional picture: an oxophilic site dissociates water while Pt binds H. Compare it with Zheng et al. 2016 and McCrum & Koper 2020.', true, 23),
