('c658e51a-ad79-5a27-b5eb-b9be20d56482', '00000000-0000-4000-8000-000000000001', null, 'Synthesis of MoS2 and MoSe2 films with vertically aligned layers', 'Kong, Cui et al.', 'Nano Lett.', 2013, '10.1021/nl400258t', 'rxn', 'Hydrogen (HER/HOR)', 'A film architecture that exposes edges by standing the layers up.', false, 27),
('895954ce-505f-5dac-9018-c7e39be082f2', '00000000-0000-4000-8000-000000000001', null, 'First-row transition metal dichalcogenide catalysts for hydrogen evolution reaction', 'Kong, Cui et al.', 'Energy Environ. Sci.', 2013, '10.1039/c3ee42413h', 'rxn', 'Hydrogen (HER/HOR)', 'Extends the chalcogenide family to Fe, Co and Ni sulfides and selenides.', false, 28),
