('adca7b95-2c86-5536-82ae-b4948e741016', '00000000-0000-4000-8000-000000000001', null, 'Product selectivity affected by cationic species in electrochemical reduction of CO2 and CO at a Cu electrode', 'Murata & Hori', 'Bull. Chem. Soc. Jpn.', 1991, '10.1246/bcsj.64.123', 'intf', 'Cations, anions and fields', 'The original observation that cation identity shifts product selectivity. Thirty years of work follows from it.', true, 95),
('112029dd-c3e2-5faf-85f1-02533ec5d4e6', '00000000-0000-4000-8000-000000000001', null, 'The role of non-covalent interactions in electrocatalytic fuel-cell reactions on platinum', 'Strmcnik, Kodama, van der Vliet, Greeley, Stamenkovic & Marković', 'Nat. Chem.', 2009, '10.1038/NCHEM.330', 'intf', 'Cations, anions and fields', 'Shows that hydrated cations that never adsorb still change ORR and HOR rates. The electrolyte becomes part of the catalyst.', true, 96),
('d63a3585-a6fe-5e9f-ad4e-fd3becbadb45', '00000000-0000-4000-8000-000000000001', null, 'Electric field effects in electrochemical CO2 reduction', 'Chen, Urushihara, Chan & Nørskov', 'ACS Catal.', 2016, '10.1021/acscatal.6b02299', 'intf', 'Cations, anions and fields', 'Intermediates with large dipoles, such as *CO2, are stabilized by the interfacial field. This is the theoretical basis for cation effects.', true, 97),
('4d8c8d8d-c5f9-5604-a7c4-061722556d13', '00000000-0000-4000-8000-000000000001', null, 'Promoter effects of alkali metal cations on the electrochemical reduction of carbon dioxide', 'Resasco, Chen, Clark, Tsai, Hahn, Jaramillo, Chan & Bell', 'J. Am. Chem. Soc.', 2017, '10.1021/jacs.7b06765', 'intf', 'Cations, anions and fields', 'Shows that cation size changes intrinsic rates through field–dipole interactions at the outer Helmholtz plane. A key paper on cation effects.', true, 98),
