('8b683f93-ff65-5df1-b535-e50f4e207a21', '00000000-0000-4000-8000-000000000001', null, 'Interfacial water reorganization as a pH-dependent descriptor of the hydrogen evolution rate on platinum electrodes', 'Ledezma-Yanez, Wallace, Sebastián-Pascual, Climent, Feliu & Koper', 'Nat. Energy', 2017, '10.1038/nenergy.2017.31', 'intf', 'pH and interfacial water', 'Uses the potential of maximum entropy to argue that interfacial water rigidity slows HER in base. The third explanation in the alkaline HER debate.', true, 104),
('c93016fc-7c27-5547-a1c2-570ba00d4deb', '00000000-0000-4000-8000-000000000001', null, 'Energy and fuels from electrochemical interfaces', 'Stamenkovic, Strmcnik, Lopes & Markovic', 'Nat. Mater.', 2017, '10.1038/NMAT4738', 'intf', 'pH and interfacial water', 'Combines covalent (adsorbate) and non-covalent (double layer) interactions in one framework. The best overview for this ring.', true, 105),
('c9f15d3d-998a-504b-ac21-9a3711f8047b', '00000000-0000-4000-8000-000000000001', null, 'Examination of near-electrode concentration gradients and kinetic impacts on the electrochemical reduction of CO2 using surface-enhanced infrared spectroscopy', 'Dunwell, Xu et al.', 'ACS Catal.', 2018, null, 'intf', 'Local concentration and transport', 'Measures surface pH from carbonate/bicarbonate bands. A method you could use directly to test local-concentration hypotheses.', true, 106),
('f7947e36-bee0-520d-9c9c-8b5990d36bee', '00000000-0000-4000-8000-000000000001', null, 'In situ infrared spectroscopy reveals persistent alkalinity near electrode surfaces during CO2 electroreduction', 'Yang, Burdyny et al.', 'J. Am. Chem. Soc.', 2019, '10.1021/jacs.9b07000', 'intf', 'Local concentration and transport', 'Shows that even a strong buffer cannot hold the surface pH at modest current. A caveat for any H-cell result that depends on local concentrations.', true, 107),
