('b05a689e-e30f-58cf-85d4-914c1cf9ae41', '00000000-0000-4000-8000-000000000001', null, 'Predicting macro-kinetic observables with the generalized degree of rate control in electrocatalysis', 'Baz, Holewinski et al.', 'J. Catal.', 2021, null, 'rigor', 'Kinetic analysis', 'Expresses the Tafel slope, apparent barrier and reaction orders in terms of the degree of rate control. It connects Campbell''s tool to electrochemical data.', false, 180),
('a906ffb6-0a78-5fcd-9195-319a47d10258', '00000000-0000-4000-8000-000000000001', null, 'Understanding the complementarities of surface-enhanced infrared and Raman spectroscopies in CO adsorption and electrochemical reduction', 'Chang, Xu et al.', 'Nat. Commun.', 2022, null, 'rigor', 'Spectroscopy and its traps', 'Shows that SEIRAS and SERS can see different populations of adsorbed CO. Important if you use either one to estimate *CO coverage.', true, 181),
('e84a194e-7edf-5059-8bda-afabb9e4c6f6', '00000000-0000-4000-8000-000000000001', null, 'Hydrogen spillover. Facts and fiction', 'Prins', 'Chem. Rev.', 2012, '10.1021/cr200346z', 'rigor', 'Spectroscopy and its traps', 'A careful audit of when spillover is real and when it is an artefact of interpretation. A model of scepticism toward attractive mechanisms.', false, 182),
('9840d268-42dc-5f74-9bf5-f3f3f1ca75f7', '00000000-0000-4000-8000-000000000001', null, 'Supported metal clusters: synthesis, structure, and catalysis', 'Gates', 'Chem. Rev.', 1995, null, 'front', 'Single sites that form and move', 'The organometallic route to well-defined supported clusters, the precursor to today''s single-site catalysts.', false, 183),
('c8a9371b-7902-5538-99db-3507fa286bfa', '00000000-0000-4000-8000-000000000001', null, 'Single-atom catalysis of CO oxidation using Pt1/FeOx', 'Qiao, Wang, Yang, Li, Zhang et al.', 'Nat. Chem.', 2011, '10.1038/nchem.1095', 'front', 'Single sites that form and move', 'The paper that named single-atom catalysis. Compare its Pt–O site with the Co–N4 site in CoPc.', true, 184),
('436bbbe1-d872-5e76-ae8d-117c2a90f9e4', '00000000-0000-4000-8000-000000000001', null, 'Single-atom catalysis: how structure influences catalytic performance', 'Parkinson', 'Catal. Lett.', 2019, null, 'front', 'Single sites that form and move', 'A surface scientist''s argument that single atoms are not all alike: their coordination sets their chemistry.', false, 185),
('d6bc2c03-1a4a-5343-b596-a08605ce705b', '00000000-0000-4000-8000-000000000001', null, 'Structural evolution of atomically dispersed Pt catalysts dictates reactivity', 'DeRita, Christopher et al.', 'Nat. Mater.', 2019, null, 'front', 'Single sites that form and move', 'The same Pt single atoms change local structure with pretreatment, and reactivity changes with them. A warning against assuming one fixed site.', true, 186),
('684e3a31-3f56-5eb4-a2b1-9794a47ae88e', '00000000-0000-4000-8000-000000000001', null, 'Dynamic multinuclear sites formed by mobilized copper ions in NOx selective catalytic reduction', 'Paolucci, Gounder, Schneider et al.', 'Science', 2017, '10.1126/science.aan5630', 'front', 'Single sites that form and move', 'Cu ions solvated by NH3 move through zeolite cages and pair up to react. Sites that exist only under reaction conditions.', true, 187),
('53497930-ef32-54d1-8eba-422ab72cae31', '00000000-0000-4000-8000-000000000001', null, 'Principles of dynamic heterogeneous catalysis: surface resonance and turnover frequency response', 'Ardagh, Abdelrahman & Dauenhauer', 'ACS Catal.', 2019, null, 'front', 'Driving catalysis dynamically', 'Oscillating binding energies can push rates above the Sabatier maximum. Pulsed potentials in electrocatalysis are one way to do this.', true, 188),
('fb6453c7-9c38-5fe0-91ec-ac9992838c63', '00000000-0000-4000-8000-000000000001', null, 'Visible-light-enhanced catalytic oxidation reactions on plasmonic silver nanostructures', 'Christopher, Xin & Linic', 'Nat. Chem.', 2011, '10.1038/nchem.1032', 'front', 'Driving catalysis dynamically', 'Light-excited plasmons speed up a thermal reaction on Ag. Another way, besides potential, to inject energy into adsorbates.', false, 189),
('8c801281-218f-5099-ac53-36cf90ee00dd', '00000000-0000-4000-8000-000000000001', null, 'Photocatalysis on TiO2 surfaces: principles, mechanisms, and selected results', 'Linsebigler, Lu & Yates', 'Chem. Rev.', 1995, '10.1021/cr00035a013', 'front', 'Driving catalysis dynamically', 'The classic surface-science review of TiO2 photocatalysis: charge carriers, trapping and how they reach adsorbates.', false, 190),
('158773a8-974f-5260-bae4-790e109ea938', '00000000-0000-4000-8000-000000000001', null, 'A simple method to approximate electrode potential-dependent activation energies using density functional theory', 'Akhade, Janik et al.', 'Catal. Today', 2017, null, 'front', 'Theory at the real interface', 'Estimates potential-dependent barriers from a chemical-step analogue plus Marcus theory, demonstrated on CO2 to *COOH.', false, 191),
